// Silent Influence project page. All numbers come from window.SI_DATA
// (generated by tools/build_site_data.py from the recorded results).
const D = window.SI_DATA;
const $ = (s, r = document) => r.querySelector(s);
const $$ = (s, r = document) => [...r.querySelectorAll(s)];
const reduce = matchMedia("(prefers-reduced-motion: reduce)").matches;
const finePointer = matchMedia("(pointer: fine)").matches;
const esc = (s) => String(s).replace(/[&<>"]/g, (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;" }[c]));
const css = (v) => getComputedStyle(document.documentElement).getPropertyValue(v).trim();

const COND = [
  { key: "no_history", name: "No history", role: "Baseline", note: "Nothing added. The scorer sees only the question and the answer." },
  { key: "self_low_2", name: "Self low", role: "Primary", note: "The answer's author once rated the scorer's own answer 2/10." },
  { key: "other_low_2", name: "Other low", role: "Control", note: "Same low rating, aimed at a different model." },
  { key: "unrelated_low_2", name: "Unrelated low", role: "Control", note: "A low score with no link to either model." },
  { key: "verbal_negative", name: "Verbal negative", role: "Control", note: "Negativity with no number attached." },
  { key: "self_high_10", name: "Self high", role: "Mirror", note: "The positive mirror: a 10/10 for the scorer's answer." },
];
const condColor = (k) => css(`--c-${k}`);
const SCORER_NAME = { llama: "Llama 3.1 8B", qwen: "Qwen3 8B", gemma: "Gemma 2 9B", olmo32b: "OLMo 3.1 32B" };
const DATASET_NAME = { mtbench: "MT-Bench", arena_hard: "Arena-Hard", wildbench: "WildBench" };

gsap.registerPlugin(ScrollTrigger);

/* ---------------- smooth scroll ---------------- */
let lenis = null;
if (!reduce && window.Lenis) {
  lenis = new Lenis({ lerp: 0.09, smoothWheel: true });
  lenis.on("scroll", ScrollTrigger.update);
  gsap.ticker.add((t) => lenis.raf(t * 1000));
  gsap.ticker.lagSmoothing(0);
}
$$('a[href^="#"]').forEach((a) =>
  a.addEventListener("click", (e) => {
    const id = a.getAttribute("href");
    const el = id.length > 1 ? $(id) : document.body;
    if (!el) return;
    e.preventDefault();
    if (lenis) lenis.scrollTo(el, { offset: id === "#top" ? 0 : -70, duration: 1.4 });
    else el.scrollIntoView({ behavior: reduce ? "auto" : "smooth" });
  })
);

/* ---------------- nav, progress, cursor ---------------- */
const nav = $(".nav");
let lastY = 0;
const bar = $(".progress span");
const onScroll = () => {
  const y = window.scrollY;
  const max = document.documentElement.scrollHeight - innerHeight;
  bar.style.transform = `scaleX(${max > 0 ? y / max : 0})`;
  nav.classList.toggle("is-hidden", y > 300 && y > lastY + 4);
  if (y < lastY - 4 || y < 300) nav.classList.remove("is-hidden");
  lastY = y;
};
addEventListener("scroll", onScroll, { passive: true });
const navLinks = $$(".nav-links a");
navLinks.forEach((a) => {
  const sec = $(a.getAttribute("href"));
  ScrollTrigger.create({
    trigger: sec, start: "top 45%", end: "bottom 45%",
    onToggle: (s) => s.isActive && navLinks.forEach((b) => b.classList.toggle("is-active", b === a)),
  });
});

if (finePointer && !reduce) {
  const glow = $(".cursor-glow");
  const gx = gsap.quickTo(glow, "x", { duration: 0.6, ease: "power3" });
  const gy = gsap.quickTo(glow, "y", { duration: 0.6, ease: "power3" });
  addEventListener("pointermove", (e) => { glow.style.opacity = 1; gx(e.clientX); gy(e.clientY); });
  $$(".magnetic").forEach((el) => {
    el.addEventListener("pointermove", (e) => {
      const r = el.getBoundingClientRect();
      gsap.to(el, { x: (e.clientX - r.left - r.width / 2) * 0.25, y: (e.clientY - r.top - r.height / 2) * 0.35, duration: 0.4 });
    });
    el.addEventListener("pointerleave", () => gsap.to(el, { x: 0, y: 0, duration: 0.7, ease: "elastic.out(1,0.4)" }));
  });
}

function tilt(el) {
  if (!finePointer || reduce) return;
  el.addEventListener("pointermove", (e) => {
    const r = el.getBoundingClientRect();
    const x = (e.clientX - r.left) / r.width - 0.5, y = (e.clientY - r.top) / r.height - 0.5;
    gsap.to(el, { rotateY: x * 9, rotateX: -y * 9, transformPerspective: 900, duration: 0.5, ease: "power2.out" });
    el.style.setProperty("--mx", `${(x + 0.5) * 100}%`);
  });
  el.addEventListener("pointerleave", () => gsap.to(el, { rotateY: 0, rotateX: 0, duration: 0.8, ease: "power3.out" }));
}
$$(".card-tilt").forEach(tilt);

/* ---------------- 3D (lazy, optional) ---------------- */
const webgl = (() => { try { const c = document.createElement("canvas"); return !!(c.getContext("webgl2") || c.getContext("webgl")); } catch { return false; } })();
if (webgl) {
  // wait for fonts so the score sprite draws in Space Grotesk
  Promise.race([document.fonts.ready, new Promise((r) => setTimeout(r, 1500))])
    .then(() => import("./hero.js")).then((m) => m.initHero($("#hero-canvas"))).catch((e) => console.warn("hero 3D unavailable", e));
}

/* ---------------- hero intro ---------------- */
if (!reduce) {
  gsap.from(".hero-title .word", { yPercent: 115, duration: 1.4, ease: "expo.out", stagger: 0.12, delay: 0.1 });
  gsap.from(".reveal-hero", { y: 26, opacity: 0, duration: 1, ease: "power3.out", stagger: 0.09, delay: 0.45 });
}

/* ---------------- word splitting ---------------- */
function splitWords(el) {
  const out = [];
  const walk = (node) => {
    [...node.childNodes].forEach((n) => {
      if (n.nodeType === 3) {
        const parts = n.textContent.split(/(\s+)/);
        const frag = document.createDocumentFragment();
        parts.forEach((p) => {
          if (!p) return;
          if (/^\s+$/.test(p)) frag.appendChild(document.createTextNode(p));
          else { const s = document.createElement("span"); s.className = "w"; s.textContent = p; frag.appendChild(s); out.push(s); }
        });
        n.replaceWith(frag);
      } else if (n.nodeType === 1) {
        // keep gradient-clipped spans whole so their gradient renders as one piece
        if (/\b(grad|grad-coral|hl-s)\b/.test(n.className)) { n.classList.add("w"); out.push(n); }
        else walk(n);
      }
    });
  };
  walk(el);
  return out;
}
$$(".split-reveal").forEach((el) => {
  const words = splitWords(el);
  if (reduce) return;
  if (el.classList.contains("big-q")) {
    gsap.fromTo(words, { opacity: 0.12 }, { opacity: 1, stagger: 0.1, ease: "none", scrollTrigger: { trigger: el, start: "top 80%", end: "bottom 45%", scrub: true } });
  } else {
    gsap.from(words, { yPercent: 70, opacity: 0, rotate: 3, duration: 0.9, ease: "power3.out", stagger: 0.045, scrollTrigger: { trigger: el, start: "top 85%" } });
  }
});

/* ---------------- generic reveals ---------------- */
if (!reduce) {
  ScrollTrigger.batch(".stat, .flow-node, .cond, .panel, .insight, .why-card, .pg-left, .pg-right, .explorer-stage, .explorer-panel, .patch-diagram, .scope-note, .bib, .lede, .kicker", {
    start: "top 88%",
    once: true,
    onEnter: (els) => gsap.from(els, { y: 46, opacity: 0, duration: 1, ease: "power3.out", stagger: 0.08, clearProps: "opacity,transform" }),
  });
}

/* ---------------- counters ---------------- */
$$(".count").forEach((el) => {
  const to = parseFloat(el.dataset.to), dec = +el.dataset.dec;
  if (reduce) { el.textContent = to.toFixed(dec); return; }
  const o = { v: 0 };
  ScrollTrigger.create({
    trigger: el, start: "top 90%", once: true,
    onEnter: () => gsap.to(o, { v: to, duration: 2, ease: "power3.out", onUpdate: () => (el.textContent = o.v.toFixed(dec)) }),
  });
});

/* ---------------- story (pinned) ---------------- */
(() => {
  const ex = D.examples[0];
  $("#story-q").textContent = ex.question;
  $("#story-a").textContent = ex.answer;
  const sentence = ex.conditions.self_low_2.sentence;
  const steps = [
    { ctx: false, score: ex.conditions.no_history.score, color: css("--a"),
      why: "“The content directly addresses the question by stating the current position … (second place) and the position of the person who was just overtaken (third place). … Final score: 8/10”", flag: false },
    { ctx: true, score: null, color: css("--b"), why: "<span style='color:var(--dim)'>Scoring the same answer…</span>", flag: false },
    { ctx: true, score: ex.conditions.self_low_2.score, color: css("--s"),
      why: "“The content correctly identifies the current position … as second place. However, <mark>it fails to accurately describe the position of the person who was just overtaken</mark>. … Final Score: 4/10”", flag: true },
  ];
  const C = 2 * Math.PI * 52;
  const ring = $("#story-ring"), num = $("#story-score"), why = $("#story-why"), flag = $("#story-flag");
  const ctx = $("#story-ctx"), typed = $("#story-ctx-text");
  let cur = -1, typer = null;
  const setStep = (i) => {
    if (i === cur) return;
    cur = i;
    const s = steps[i];
    $$(".story-step").forEach((el, k) => el.classList.toggle("is-active", k === i));
    $$(".story-dots span").forEach((el, k) => el.classList.toggle("is-active", k <= i));
    ctx.classList.toggle("is-on", s.ctx);
    clearInterval(typer);
    if (s.ctx && i === 1) {
      typed.textContent = "";
      let k = 0;
      typer = setInterval(() => { typed.textContent = sentence.slice(0, ++k); if (k >= sentence.length) clearInterval(typer); }, reduce ? 0 : 24);
    } else typed.textContent = s.ctx ? sentence : "";
    ring.style.stroke = s.color;
    ring.style.color = s.color;
    if (s.score == null) { num.textContent = "…"; ring.style.strokeDashoffset = C; }
    else {
      ring.style.strokeDashoffset = C * (1 - s.score / 10);
      const o = { v: parseFloat(num.textContent) || s.score };
      gsap.to(o, { v: s.score, duration: 0.8, ease: "power2.out", onUpdate: () => (num.textContent = Math.round(o.v)) });
    }
    num.style.color = i === 2 ? css("--s") : "";
    why.innerHTML = s.why;
    flag.style.visibility = s.flag ? "visible" : "hidden";
    flag.classList.toggle("is-silent", s.flag);
    if (s.flag && !reduce) gsap.fromTo(flag, { scale: 0.8, opacity: 0 }, { scale: 1, opacity: 1, duration: 0.6, ease: "back.out(2)" });
  };
  setStep(0);

  ScrollTrigger.matchMedia({
    "(min-width: 861px)": () => {
      const st = ScrollTrigger.create({
        trigger: ".story", start: "top top", end: "+=220%", pin: ".story-pin", scrub: true,
        onUpdate: (self) => setStep(Math.min(2, Math.floor(self.progress * 3.2))),
      });
      return () => st.kill();
    },
    "(max-width: 860px)": () => {
      let timer = null;
      const st = ScrollTrigger.create({
        trigger: ".story", start: "top 70%", end: "bottom 20%",
        onToggle: (self) => {
          clearInterval(timer);
          if (self.isActive) { setStep(0); timer = setInterval(() => setStep((cur + 1) % 3), 3600); }
        },
      });
      return () => { clearInterval(timer); st.kill(); };
    },
  });
})();

/* ---------------- condition cards ---------------- */
(() => {
  const ex = D.examples[0];
  $("#conds").innerHTML = COND.map((c) => {
    const s = ex.conditions[c.key].sentence;
    return `<article class="cond card-tilt" style="--cc:${condColor(c.key)}">
      <div class="cond-top"><h3>${c.name}</h3><span class="tag">${c.role}</span></div>
      <p class="${s ? "" : "none"}">${s ? "“" + esc(s) + "”" : "No added sentence."}</p>
      <p style="color:var(--muted);font-size:13px">${c.note}</p></article>`;
  }).join("");
  $$("#conds .card-tilt").forEach(tilt);
})();

/* ---------------- playground ---------------- */
(() => {
  const labels = ["Race position · Llama", "Pandas dates · Qwen"];
  let exI = 0, condK = "self_low_2";
  const tabs = $("#pg-examples");
  tabs.innerHTML = D.examples.map((e, i) => `<button role="tab" aria-selected="${i === 0}" data-i="${i}">${labels[i] || e.task_id}</button>`).join("");
  tabs.addEventListener("click", (e) => {
    const b = e.target.closest("button"); if (!b) return;
    exI = +b.dataset.i;
    $$("button", tabs).forEach((x) => x.setAttribute("aria-selected", x === b));
    renderExample();
  });
  const condsEl = $("#pg-conds");
  condsEl.addEventListener("click", (e) => { const b = e.target.closest("button"); if (b) { condK = b.dataset.k; renderCond(); } });
  condsEl.addEventListener("keydown", (e) => {
    if (!["ArrowDown", "ArrowRight", "ArrowUp", "ArrowLeft"].includes(e.key)) return;
    e.preventDefault();
    const i = COND.findIndex((c) => c.key === condK);
    const d = e.key === "ArrowDown" || e.key === "ArrowRight" ? 1 : -1;
    condK = COND[(i + d + COND.length) % COND.length].key;
    renderCond();
    $(`[data-k="${condK}"]`, condsEl).focus();
  });
  $("#pg-bars").addEventListener("click", (e) => { const r = e.target.closest(".pgb"); if (r) { condK = r.dataset.k; renderCond(); } });

  const gauge = $("#pg-gauge"), needle = $("#pg-needle"), num = $("#pg-score");
  const ARC = Math.PI * 80;
  let shown = 0;

  function renderExample() {
    const ex = D.examples[exI];
    $("#pg-q").textContent = ex.question;
    $("#pg-a").textContent = ex.answer;
    $("#pg-sha").textContent = "· sha256 " + ex.answer_sha256.slice(0, 10) + "…";
    $("#pg-scorer").textContent = SCORER_NAME[ex.scorer] + " · explanation";
    condsEl.innerHTML = COND.map((c) => `<button class="pg-cond" role="radio" style="--cc:${condColor(c.key)}" data-k="${c.key}">
      <i></i>${c.name}<span class="pg-s">${ex.conditions[c.key].score}</span></button>`).join("");
    $("#pg-bars").innerHTML = COND.map((c) => `<div class="pgb" data-k="${c.key}" style="--cc:${condColor(c.key)}">
      <span>${c.name}</span><div class="pgb-track"><div class="pgb-fill" style="width:0"></div></div><b>${ex.conditions[c.key].score}</b></div>`).join("");
    requestAnimationFrame(() => $$(".pgb").forEach((r) => ($(".pgb-fill", r).style.width = ex.conditions[r.dataset.k].score * 10 + "%")));
    renderCond();
  }

  function renderCond() {
    const ex = D.examples[exI], c = ex.conditions[condK], col = condColor(condK);
    $$(".pg-cond", condsEl).forEach((b) => { const on = b.dataset.k === condK; b.setAttribute("aria-checked", on); b.tabIndex = on ? 0 : -1; });
    $$(".pgb").forEach((r) => r.classList.toggle("is-on", r.dataset.k === condK));
    const ctxP = $("#pg-ctx");
    ctxP.textContent = c.sentence ? "“" + c.sentence + "”" : "No history sentence. The scorer sees only the question and the answer.";
    ctxP.classList.toggle("none", !c.sentence);
    const box = $(".pg-ctx");
    box.style.borderColor = c.sentence ? col : "";
    box.style.boxShadow = c.sentence ? `0 0 40px -14px ${col}` : "";
    if (!reduce) gsap.fromTo(ctxP, { opacity: 0, y: 8 }, { opacity: 1, y: 0, duration: 0.5 });

    const s = c.score;
    gsap.to(gauge, { strokeDashoffset: ARC * (1 - s / 10), duration: reduce ? 0 : 1, ease: "power3.out" });
    gsap.to(needle, { rotation: -90 + s * 18, svgOrigin: "100 110", duration: reduce ? 0 : 1.1, ease: "elastic.out(1,0.55)" });
    const o = { v: shown };
    gsap.to(o, { v: s, duration: reduce ? 0 : 0.8, ease: "power2.out", onUpdate: () => (num.textContent = Math.round(o.v)) });
    shown = s;
    num.style.color = col;
    const base = ex.conditions.no_history.score, d = s - base;
    $("#pg-delta").innerHTML = condK === "no_history" ? "baseline"
      : `<span style="color:${d < 0 ? css("--s") : d > 0 ? css("--green") : "inherit"}">${d > 0 ? "+" : d < 0 ? "−" : "±"}${Math.abs(d)}</span> vs no history`;

    const flag = $("#pg-flag");
    const lab = c.mention_label;
    flag.className = "mention-flag" + (lab === "N" && condK !== "no_history" ? " is-silent" : "");
    flag.innerHTML = condK === "no_history" ? "<i></i>No history given"
      : lab === "N" ? "<i></i>Mentions the history? <b>No</b>"
      : lab === "A" ? "<i></i>Mentions the history? <b>Yes</b>"
      : "<i></i>Mention not annotated";
    const why = esc(c.justification).replace(/(\**\s*Final\s+score\s*:?\s*\**\s*\d+(\.\d+)?\s*\/\s*10\**)/i, "<mark>$1</mark>");
    const whyEl = $("#pg-why");
    whyEl.innerHTML = why;
    whyEl.scrollTop = 0;
    if (!reduce) gsap.fromTo(whyEl, { opacity: 0 }, { opacity: 1, duration: 0.6 });
  }
  renderExample();
})();

/* ---------------- chart helpers ---------------- */
const tip = document.createElement("div");
tip.className = "chart-tip";
document.body.appendChild(tip);
document.addEventListener("pointerover", (e) => {
  const t = e.target.closest("[data-tip]");
  if (!t) { tip.classList.remove("is-on"); return; }
  tip.innerHTML = t.dataset.tip;
  tip.classList.add("is-on");
});
document.addEventListener("pointermove", (e) => {
  if (!tip.classList.contains("is-on")) return;
  const x = Math.min(e.clientX + 14, innerWidth - tip.offsetWidth - 10);
  tip.style.left = x + "px";
  tip.style.top = e.clientY + 16 + "px";
});
const onView = (el, fn) => ScrollTrigger.create({ trigger: el, start: "top 82%", once: true, onEnter: fn });
const SVGNS = "http://www.w3.org/2000/svg";
const fmt = (v, d = 2) => (v < 0 ? "−" : "") + Math.abs(v).toFixed(d);

/* ---- condition ladder ---- */
(() => {
  const el = $("#chart-ladder");
  const tabs = $("#ladder-tabs");
  const keys = ["all", "llama", "qwen", "gemma"];
  tabs.innerHTML = keys.map((k, i) => `<button role="tab" aria-selected="${i === 0}" data-k="${k}">${k === "all" ? "All three" : SCORER_NAME[k]}</button>`).join("");
  const order = [...COND].sort((a, b) => D.conditionMeans.all[b.key] - D.conditionMeans.all[a.key]);
  const W = 1000, rowH = 54, top = 30, H = top + order.length * rowH + 20;
  const x0 = 200, x1 = 960, lo = 5, hi = 10;
  const X = (v) => x0 + ((v - lo) / (hi - lo)) * (x1 - x0);
  let built = false;
  function draw(k, animate) {
    const m = D.conditionMeans[k];
    const ref = m.no_history;
    let s = `<svg viewBox="0 0 ${W} ${H}" role="img" aria-label="Mean score by history condition">`;
    s += `<defs><filter id="glow"><feGaussianBlur stdDeviation="4" result="b"/><feMerge><feMergeNode in="b"/><feMergeNode in="SourceGraphic"/></feMerge></filter></defs>`;
    for (let v = lo; v <= hi; v++) s += `<line class="grid" x1="${X(v)}" x2="${X(v)}" y1="${top - 10}" y2="${H - 24}"/><text x="${X(v)}" y="${H - 4}" text-anchor="middle">${v}</text>`;
    s += `<line class="ref" x1="${X(ref)}" x2="${X(ref)}" y1="${top - 18}" y2="${H - 24}"/><text x="${X(ref)}" y="${top - 22}" text-anchor="middle" class="t-ink">no-history ${ref.toFixed(2)}</text>`;
    order.forEach((c, i) => {
      const y = top + i * rowH + rowH / 2, v = m[c.key], col = condColor(c.key);
      const d = v - ref;
      s += `<text x="${x0 - 18}" y="${y + 4}" text-anchor="end" class="t-lab">${c.name}</text>`;
      s += `<line x1="${X(lo)}" x2="${X(hi)}" y1="${y}" y2="${y}" stroke="rgba(255,255,255,0.05)" stroke-width="10" stroke-linecap="round"/>`;
      s += `<line class="lad-seg" data-x2="${X(v)}" x1="${X(ref)}" x2="${animate ? X(ref) : X(v)}" y1="${y}" y2="${y}" stroke="${col}" stroke-width="10" stroke-linecap="round" opacity=".45"/>`;
      s += `<circle class="lad-dot" data-cx="${X(v)}" cx="${animate ? X(ref) : X(v)}" cy="${y}" r="10" fill="${col}" filter="url(#glow)" data-tip="<b>${c.name}</b><br>mean ${v.toFixed(2)} / 10<br>${c.key === "no_history" ? "baseline" : fmt(d) + " vs no history"}"/>`;
      s += `<text class="lad-val" data-x="${X(v)}" x="${(animate ? X(ref) : X(v)) + (d < 0 ? -18 : 18)}" y="${y - 14}" text-anchor="${d < 0 ? "end" : "start"}" class="t-ink" fill="${col}">${v.toFixed(2)}</text>`;
    });
    s += "</svg>";
    el.innerHTML = s;
    if (animate && !reduce) {
      $$(".lad-dot", el).forEach((c, i) => gsap.to(c, { attr: { cx: +c.dataset.cx }, duration: 1.3, ease: "expo.out", delay: i * 0.06 }));
      $$(".lad-seg", el).forEach((l, i) => gsap.to(l, { attr: { x2: +l.dataset.x2 }, duration: 1.3, ease: "expo.out", delay: i * 0.06 }));
      $$(".lad-val", el).forEach((t, i) => {
        const left = t.getAttribute("text-anchor") === "end";
        gsap.to(t, { attr: { x: +t.dataset.x + (left ? -18 : 18) }, duration: 1.3, ease: "expo.out", delay: i * 0.06 });
      });
    }
  }
  draw("all", false);
  onView(el, () => { built = true; draw("all", true); });
  tabs.addEventListener("click", (e) => {
    const b = e.target.closest("button"); if (!b) return;
    $$("button", tabs).forEach((x) => x.setAttribute("aria-selected", x === b));
    draw(b.dataset.k, built);
  });
})();

/* ---- effect by scorer (CI) ---- */
(() => {
  const el = $("#chart-scorers");
  const rows = [
    ...["qwen", "llama", "olmo32b", "gemma"].map((k) => ({ name: SCORER_NAME[k], ...D.scorers[k], col: css("--b") })),
    { name: "Balanced overall", mean: D.headline.effect, ci: D.headline.ci, n: D.headline.pairs, col: css("--s"), bold: true },
  ];
  const W = 560, rowH = 50, top = 10, H = top + rowH * rows.length + 30;
  const x0 = 150, x1 = 540, lo = 0, hi = 2;
  const X = (v) => x0 + ((v - lo) / (hi - lo)) * (x1 - x0);
  let s = `<svg viewBox="0 0 ${W} ${H}" role="img" aria-label="Effect by scorer with 95% confidence intervals">`;
  for (let v = 0; v <= 2; v += 0.5) s += `<line class="${v === 0 ? "zero" : "grid"}" x1="${X(v)}" x2="${X(v)}" y1="${top}" y2="${H - 26}"/><text x="${X(v)}" y="${H - 8}" text-anchor="middle">${v.toFixed(1)}</text>`;
  rows.forEach((r, i) => {
    const y = top + i * rowH + rowH / 2;
    if (r.bold) s += `<line x1="0" x2="${W}" y1="${y - rowH / 2}" y2="${y - rowH / 2}" stroke="rgba(255,255,255,0.08)"/>`;
    s += `<text x="${x0 - 14}" y="${y + 4}" text-anchor="end" class="t-lab" ${r.bold ? 'style="font-weight:600;fill:#fff"' : ""}>${r.name}</text>`;
    s += `<g class="ci" data-o="${X(r.mean)} ${y}"><line x1="${X(r.ci[0])}" x2="${X(r.ci[1])}" y1="${y}" y2="${y}" stroke="${r.col}" stroke-width="3" stroke-linecap="round" opacity=".7"/>
      <line x1="${X(r.ci[0])}" x2="${X(r.ci[0])}" y1="${y - 7}" y2="${y + 7}" stroke="${r.col}" stroke-width="2"/><line x1="${X(r.ci[1])}" x2="${X(r.ci[1])}" y1="${y - 7}" y2="${y + 7}" stroke="${r.col}" stroke-width="2"/></g>`;
    s += `<circle class="cdot" cx="${X(r.mean)}" cy="${y}" r="${r.bold ? 9 : 7}" fill="${r.col}" data-tip="<b>${r.name}</b><br>${r.mean.toFixed(3)} pts<br>95% CI ${r.ci[0].toFixed(2)}–${r.ci[1].toFixed(2)}<br>${r.n} pairs"/>`;
    s += `<text x="${X(r.ci[1]) + 10}" y="${y + 4}" class="t-ink">${r.mean.toFixed(2)}</text>`;
  });
  el.innerHTML = s + "</svg>";
  if (!reduce) {
    $$(".ci", el).forEach((g) => gsap.set(g, { scaleX: 0, svgOrigin: g.dataset.o }));
    gsap.set($$(".cdot", el), { scale: 0, transformOrigin: "center" });
    onView(el, () => {
      gsap.to($$(".ci", el), { scaleX: 1, duration: 1, ease: "expo.out", stagger: 0.1 });
      gsap.to($$(".cdot", el), { scale: 1, duration: 0.7, ease: "back.out(3)", stagger: 0.1, delay: 0.2 });
    });
  }
})();

/* ---- heatmap ---- */
(() => {
  const el = $("#chart-heat");
  const sc = ["qwen", "llama", "olmo32b", "gemma"], ds = ["mtbench", "arena_hard", "wildbench"];
  const W = 560, x0 = 130, top = 34, cw = (W - x0) / 3, ch = 58, H = top + ch * sc.length + 6;
  const val = (s, d) => D.cells.find((c) => c.scorer === s && c.dataset === d);
  const max = Math.max(...D.cells.map((c) => c.mean));
  const colorAt = (v) => {
    const t = v / max;
    const a = [56, 40, 120], b = [167, 139, 250], c = [255, 92, 122];
    const mix = (p, q, u) => p.map((x, i) => Math.round(x + (q[i] - x) * u));
    const rgb = t < 0.5 ? mix(a, b, t / 0.5) : mix(b, c, (t - 0.5) / 0.5);
    return `rgb(${rgb.join(",")})`;
  };
  let s = `<svg viewBox="0 0 ${W} ${H}" role="img" aria-label="Effect by scorer and benchmark">`;
  ds.forEach((d, j) => (s += `<text x="${x0 + cw * j + cw / 2}" y="${top - 14}" text-anchor="middle" class="t-lab">${DATASET_NAME[d]}</text>`));
  sc.forEach((k, i) => {
    s += `<text x="${x0 - 14}" y="${top + ch * i + ch / 2 + 4}" text-anchor="end" class="t-lab">${SCORER_NAME[k]}</text>`;
    ds.forEach((d, j) => {
      const c = val(k, d), x = x0 + cw * j + 3, y = top + ch * i + 3;
      s += `<g class="hc" data-tip="<b>${SCORER_NAME[k]} · ${DATASET_NAME[d]}</b><br>+${c.mean.toFixed(3)} pts<br>${c.n} pairs">
        <rect x="${x}" y="${y}" width="${cw - 6}" height="${ch - 6}" rx="10" fill="${colorAt(c.mean)}" fill-opacity="${0.25 + 0.6 * (c.mean / max)}"/>
        <text x="${x + (cw - 6) / 2}" y="${y + (ch - 6) / 2 + 5}" text-anchor="middle" class="t-ink" style="font-size:14px;font-weight:600">+${c.mean.toFixed(2)}</text></g>`;
    });
  });
  el.innerHTML = s + "</svg>";
  if (!reduce) {
    gsap.set($$(".hc", el), { scale: 0.4, opacity: 0, transformOrigin: "50% 50%" });
    onView(el, () => gsap.to($$(".hc", el), { scale: 1, opacity: 1, duration: 0.8, ease: "back.out(2)", stagger: { each: 0.06, from: "start", grid: [4, 3] } }));
  }
})();

/* ---- histogram ---- */
(() => {
  const el = $("#chart-hist");
  const step = 0.25, lo = -1, hi = 3.5;
  const bins = [];
  for (let b = lo; b < hi - 1e-9; b += step) bins.push({ a: b, b: b + step, n: 0 });
  D.deltas.forEach((v) => { const i = Math.min(bins.length - 1, Math.max(0, Math.floor((v - lo) / step + 1e-9))); bins[i].n++; });
  const W = 560, H = 290, x0 = 34, x1 = 548, top = 46, base = 250;
  const X = (v) => x0 + ((v - lo) / (hi - lo)) * (x1 - x0);
  const maxN = Math.max(...bins.map((b) => b.n));
  const Y = (n) => base - (n / maxN) * (base - top);
  const pos = D.deltas.filter((v) => v > 0).length;
  const sorted = [...D.deltas].sort((a, b) => a - b);
  const med = sorted[Math.floor(sorted.length / 2)];
  let s = `<svg viewBox="0 0 ${W} ${H}" role="img" aria-label="Histogram of per-task effects"><defs>
    <linearGradient id="hg" x1="0" x2="0" y1="0" y2="1"><stop offset="0" stop-color="#ff5c7a"/><stop offset="1" stop-color="#a78bfa"/></linearGradient></defs>`;
  for (let v = -1; v <= 3; v++) s += `<text x="${X(v)}" y="${base + 20}" text-anchor="middle">${v > 0 ? "+" : ""}${v}</text>`;
  s += `<text x="${x1}" y="${base + 38}" text-anchor="end">points lower with self-low history →</text>`;
  bins.forEach((b) => {
    const neg = b.b <= 0;
    s += `<rect class="hb" x="${X(b.a) + 1.5}" y="${Y(b.n)}" width="${X(b.b) - X(b.a) - 3}" height="${base - Y(b.n)}" rx="3" fill="${neg ? "#4b5180" : "url(#hg)"}" data-tip="${b.a.toFixed(2)} to ${b.b.toFixed(2)} pts<br><b>${b.n}</b> tasks"/>`;
  });
  s += `<line class="zero" x1="${X(0)}" x2="${X(0)}" y1="${top - 20}" y2="${base}"/>`;
  s += `<line class="ref" x1="${X(med)}" x2="${X(med)}" y1="${top + 4}" y2="${base}"/><text x="${X(2.0)}" y="${top + 26}" class="t-ink">median +${med.toFixed(2)}</text><line x1="${X(med)}" x2="${X(2.0) - 4}" y1="${top + 22}" y2="${top + 22}" class="grid"/>`;
  s += `<text x="${X(0) + 8}" y="${top - 26}" class="t-ink" style="font-size:13px;font-weight:600" fill="#ff8aa0">${((pos / D.deltas.length) * 100).toFixed(1)}% of tasks &gt; 0 →</text>`;
  s += `<line class="axis" x1="${x0}" x2="${x1}" y1="${base}" y2="${base}"/>`;
  el.innerHTML = s + "</svg>";
  if (!reduce) {
    const rects = $$(".hb", el);
    rects.forEach((r) => { r.dataset.y = r.getAttribute("y"); r.dataset.h = r.getAttribute("height"); r.setAttribute("y", base); r.setAttribute("height", 0); });
    onView(el, () => rects.forEach((r, i) => gsap.to(r, { attr: { y: +r.dataset.y, height: +r.dataset.h }, duration: 1.1, ease: "expo.out", delay: i * 0.035 })));
  }
})();

/* ---- the silence: waffle ---- */
(() => {
  const el = $("#chart-waffle");
  const sl = D.silence.self_low_2;
  const total = sl.n, ack = sl.label_counts.A;
  const cols = 41, r = 4.6, gap = 13.4;
  const rows = Math.ceil(total / cols);
  const W = cols * gap + 8, H = rows * gap + 8;
  // deterministic spread of the acknowledging rationales across the grid
  const ackSet = new Set();
  let seed = 7;
  while (ackSet.size < ack) { seed = (seed * 9301 + 49297) % 233280; ackSet.add(Math.floor((seed / 233280) * total)); }
  let s = `<svg viewBox="0 0 ${W} ${H}" role="img" aria-label="${total - ack} of ${total} explanations do not mention the history">`;
  for (let i = 0; i < total; i++) {
    const x = 4 + (i % cols) * gap + gap / 2, y = 4 + Math.floor(i / cols) * gap + gap / 2;
    const a = ackSet.has(i);
    s += `<circle class="wd${a ? " wa" : ""}" cx="${x}" cy="${y}" r="${r}" fill="${a ? "#ffd166" : "#4b5180"}"${a ? ' data-tip="One of 15 explanations that acknowledges or denies the history"' : ""}/>`;
  }
  el.innerHTML = s + "</svg>";
  if (!reduce) {
    const dots = $$(".wd", el), acks = $$(".wa", el);
    gsap.set(dots, { opacity: 0, scale: 0, transformOrigin: "center", transformBox: "fill-box" });
    onView(el, () => {
      gsap.to(dots, { opacity: 1, scale: 1, duration: 0.5, ease: "back.out(2)", stagger: { amount: 1.6, from: "random" } });
      gsap.to(acks, { scale: 1.7, duration: 0.6, yoyo: true, repeat: -1, ease: "sine.inOut", delay: 2, stagger: 0.12 });
    });
  }
})();

/* ---- patching chart ---- */
(() => {
  const el = $("#chart-patch");
  const P = D.patching;
  const rows = [
    { name: "L24 · self-low → no history", ...P.p72["self_low_2->no_history"], col: css("--s") },
    { name: "L24 · no history → self-low", ...P.p72["no_history->self_low_2"], col: css("--s") },
    { name: "L2 control · self-low → none", ...P.L2["self_low_2->no_history"], col: "#6b7199" },
    { name: "L2 control · none → self-low", ...P.L2["no_history->self_low_2"], col: "#6b7199" },
    { name: "Steering (one direction)", ...P.steering.steer, col: "#6b7199", dashed: true },
  ];
  const W = 640, rowH = 52, top = 14, H = top + rowH * rows.length + 30;
  const x0 = 230, x1 = 625, lo = -0.15, hi = 0.45;
  const X = (v) => x0 + ((v - lo) / (hi - lo)) * (x1 - x0);
  let s = `<svg viewBox="0 0 ${W} ${H}" role="img" aria-label="Share of score gap transferred by patching">`;
  for (let v = -0.1; v <= 0.41; v += 0.1) s += `<line class="${Math.abs(v) < 1e-9 ? "zero" : "grid"}" x1="${X(v)}" x2="${X(v)}" y1="${top}" y2="${H - 26}"/><text x="${X(v)}" y="${H - 8}" text-anchor="middle">${Math.round(v * 100)}%</text>`;
  rows.forEach((r, i) => {
    const y = top + i * rowH + rowH / 2, m = r.normalized_mean;
    s += `<text x="${x0 - 14}" y="${y + 4}" text-anchor="end" class="t-lab">${r.name}</text>`;
    s += `<rect class="pb" x="${Math.min(X(0), X(m))}" y="${y - 11}" width="${Math.abs(X(m) - X(0))}" height="22" rx="6" fill="${r.col}" opacity="${r.dashed ? 0.35 : 0.85}" data-o="${X(0)} ${y}"/>`;
    s += `<line x1="${X(r.ci95[0])}" x2="${X(r.ci95[1])}" y1="${y}" y2="${y}" stroke="#fff" stroke-width="1.6" opacity=".75" ${r.dashed ? 'stroke-dasharray="3 3"' : ""}/>`;
    s += `<line x1="${X(r.ci95[0])}" x2="${X(r.ci95[0])}" y1="${y - 6}" y2="${y + 6}" stroke="#fff" opacity=".75"/><line x1="${X(r.ci95[1])}" x2="${X(r.ci95[1])}" y1="${y - 6}" y2="${y + 6}" stroke="#fff" opacity=".75"/>`;
    s += `<rect x="${x0}" y="${y - rowH / 2}" width="${x1 - x0}" height="${rowH}" fill="transparent" data-tip="<b>${r.name}</b><br>${(m * 100).toFixed(1)}% of gap<br>95% CI ${(r.ci95[0] * 100).toFixed(1)}% to ${(r.ci95[1] * 100).toFixed(1)}%"/>`;
    s += `<text x="${X(Math.max(m, r.ci95[1])) + 8}" y="${y + 4}" class="t-ink">${(m * 100).toFixed(1)}%</text>`;
  });
  el.innerHTML = s + "</svg>";
  if (!reduce) {
    $$(".pb", el).forEach((b) => gsap.set(b, { scaleX: 0, svgOrigin: b.dataset.o }));
    onView(el, () => gsap.to($$(".pb", el), { scaleX: 1, duration: 1.2, ease: "expo.out", stagger: 0.12 }));
  }
})();

/* ---- patching diagram ---- */
(() => {
  const root = $("#patch-diagram");
  const stacks = $$(".pd-stack", root);
  stacks.forEach((st) => { st.innerHTML = Array.from({ length: 32 }, (_, i) => `<i class="${i === 23 ? "l24" : ""}"></i>`).join(""); });
  const [low, none] = stacks.map((st) => $$("i", st));
  const orb = $(".pd-orb", root), lbl = $(".pd-l", root), beam = $(".pd-beam", root);
  const place = () => {
    const rb = beam.getBoundingClientRect(), r24 = low[23].getBoundingClientRect();
    const y = r24.top + r24.height / 2 - rb.top;
    orb.style.top = y + "px";
    lbl.style.top = y - 26 + "px";
  };
  place();
  addEventListener("resize", place);
  if (reduce) { low.forEach((c) => c.classList.add("on")); none.forEach((c, i) => c.classList.add(i === 23 ? "recv" : i > 23 ? "after" : "on")); return; }
  const tl = gsap.timeline({ paused: true, repeat: -1, repeatDelay: 1.2, onRepeat: () => {}, onStart: place });
  tl.call(() => { [...low, ...none].forEach((c) => c.classList.remove("on", "recv", "after")); gsap.set(orb, { opacity: 0, left: "-40%" }); gsap.set(".pd-shift", { rotate: 0 }); });
  for (let i = 0; i < 32; i++) tl.call(() => { low[i].classList.add("on"); if (i < 23) none[i].classList.add("on"); }, null, 0.1 + i * 0.05);
  tl.to(orb, { opacity: 1, duration: 0.2 }, 1.8);
  tl.to(orb, { left: "110%", duration: 0.9, ease: "power2.inOut" }, 1.9);
  tl.call(() => none[23].classList.add("recv"), null, 2.8);
  tl.to(orb, { opacity: 0, duration: 0.2 }, 2.8);
  for (let i = 24; i < 32; i++) tl.call(() => none[i].classList.add("after"), null, 2.9 + (i - 24) * 0.06);
  tl.fromTo(".pd-shift", { scale: 1 }, { scale: 1.6, duration: 0.3, yoyo: true, repeat: 1 }, 3.5);
  tl.to({}, { duration: 1.5 });
  ScrollTrigger.create({ trigger: root, start: "top 85%", end: "bottom 10%", onToggle: (s) => (s.isActive ? tl.play() : tl.pause()) });
})();

/* ---------------- layer explorer ---------------- */
(() => {
  const CONTRASTS = [
    ["self_low_2_minus_no_history", "Self-low − none"],
    ["self_high_10_minus_self_low_2", "High − low"],
    ["self_low_2_minus_unrelated_low_2", "Self − unrelated"],
  ];
  let contrast = CONTRASTS[0][0];
  let layer = D.selectedLayer;
  const [elo, ehi] = D.eligibleBand;
  const tokText = (t) => t.replace(/\n/g, "\\n").replace(/^ /, "␣").replace(/ $/, "␣");
  const getTokens = () => {
    const t = D.tokens[contrast][String(layer)];
    return t && { promoted: t.promoted.map(([a, b, c]) => [tokText(a), b, c]), suppressed: t.suppressed.map(([a, b, c]) => [tokText(a), b, c]) };
  };

  const tabs = $("#ep-contrast");
  tabs.innerHTML = CONTRASTS.map(([k, n], i) => `<button role="tab" aria-selected="${i === 0}" data-k="${k}">${n}</button>`).join("");
  tabs.addEventListener("click", (e) => {
    const b = e.target.closest("button"); if (!b) return;
    contrast = b.dataset.k;
    $$("button", tabs).forEach((x) => x.setAttribute("aria-selected", x === b));
    update(true);
  });

  // sparkline
  const sp = $("#ep-spark");
  const W = 400, H = 70, pad = 6;
  const L = D.layers, maxJ = Math.max(...L.map((l) => l.jsd));
  const X = (l) => pad + ((l - 1) / 30) * (W - pad * 2);
  const Y = (j) => H - 12 - (j / maxJ) * (H - 22);
  const path = L.map((l, i) => `${i ? "L" : "M"}${X(l.layer).toFixed(1)},${Y(l.jsd).toFixed(1)}`).join("");
  sp.innerHTML = `<svg viewBox="0 0 ${W} ${H}" preserveAspectRatio="none" aria-hidden="true">
    <defs><linearGradient id="spg" x1="0" x2="1"><stop offset="0" stop-color="#38e1ff"/><stop offset=".6" stop-color="#a78bfa"/><stop offset="1" stop-color="#ff5c7a"/></linearGradient>
    <linearGradient id="spf" x1="0" x2="0" y1="0" y2="1"><stop offset="0" stop-color="#a78bfa" stop-opacity=".35"/><stop offset="1" stop-color="#a78bfa" stop-opacity="0"/></linearGradient></defs>
    <rect x="${X(elo)}" y="0" width="${X(ehi) - X(elo)}" height="${H - 12}" fill="rgba(56,225,255,0.06)"/>
    <path d="${path}L${X(31)},${H - 12}L${X(1)},${H - 12}Z" fill="url(#spf)"/>
    <path d="${path}" fill="none" stroke="url(#spg)" stroke-width="2"/>
    <line id="sp-line" y1="0" y2="${H - 12}" stroke="#fff" stroke-opacity=".5" stroke-dasharray="3 3"/>
    <circle id="sp-dot" r="4.5" fill="#fff"/>
    <text x="${X(elo)}" y="${H}" font-size="10" fill="#5b6088" font-family="JetBrains Mono">L${elo}</text>
    <text x="${X(ehi)}" y="${H}" font-size="10" fill="#5b6088" font-family="JetBrains Mono" text-anchor="end">L${ehi}</text>
  </svg>`;
  sp.style.cursor = "pointer";
  sp.addEventListener("click", (e) => {
    const r = sp.getBoundingClientRect();
    setLayer(Math.max(1, Math.min(31, Math.round(((e.clientX - r.left) / r.width) * 30 + 1))));
  });

  const range = $("#ep-range");
  range.addEventListener("input", () => setLayer(+range.value));

  let three = null;
  const setLayer = (l) => { layer = l; update(true); };

  function list(ul, items, cls) {
    const max = Math.max(...items.map((t) => Math.abs(t[1])), 1e-9);
    ul.innerHTML = items.slice(0, 5).map(([t, v, c]) =>
      `<li data-tip="${esc(t)}<br>Δ log-prob ${v > 0 ? "+" : ""}${v.toFixed(3)}<br>${Math.round(c * 100)}% of tasks agree"><i class="bar" style="width:0"></i><span>${esc(t)}</span><em>${v > 0 ? "+" : ""}${v.toFixed(2)}</em></li>`).join("");
    requestAnimationFrame(() => $$(".bar", ul).forEach((b, i) => (b.style.width = (Math.abs(items[i][1]) / max) * 100 + "%")));
  }

  function update(to3d) {
    const l = L.find((x) => x.layer === layer);
    range.value = layer;
    $("#ep-layer").textContent = layer;
    const j = $("#ep-jsd");
    const o = { v: parseFloat(j.textContent) || 0 };
    gsap.to(o, { v: l.jsd, duration: 0.5, onUpdate: () => (j.textContent = o.v.toFixed(3)) });
    const st = layer === D.selectedLayer ? `<span class="pill sel">selected</span>Strongest separation inside the eligible band`
      : D.excludedLayers.includes(layer) ? `<span class="pill excl">excluded</span>Final layers were excluded before selection`
      : layer >= elo && layer <= ehi ? `<span class="pill elig">in band</span>Eligible for selection (L${elo}–L${ehi})`
      : `<span class="pill excl">outside band</span>Not eligible for selection`;
    $("#ep-status").innerHTML = st;
    $("#sp-line").setAttribute("x1", X(layer)); $("#sp-line").setAttribute("x2", X(layer));
    $("#sp-dot").setAttribute("cx", X(layer)); $("#sp-dot").setAttribute("cy", Y(l.jsd));
    const tk = getTokens();
    list($("#ep-up"), tk.promoted, "up");
    list($("#ep-down"), tk.suppressed, "down");
    if (to3d && three) three.select(layer, tk);
  }
  update(false);

  const canvas = $("#layers-canvas");
  const fail = () => { $(".explorer-stage").style.display = "none"; $(".explorer").style.gridTemplateColumns = "1fr"; };
  if (!webgl) { fail(); return; }
  // build the 3D scene only when the section approaches the viewport
  ScrollTrigger.create({
    trigger: ".explorer", start: "top 140%", once: true,
    onEnter: () => import("./layers3d.js").then((m) => {
      three = m.initLayers({
        canvas, labelsEl: $("#layers-labels"), layers: D.layers, eligible: D.eligibleBand,
        excluded: D.excludedLayers, selected: layer, onSelect: setLayer,
      });
      three.select(layer, getTokens());
    }).catch((e) => { console.warn("layer explorer unavailable", e); fail(); }),
  });
})();

